<template>
  <section><RouterLink to="/lms/courses" class="small text-secondary"><i class="bi bi-arrow-left me-1"></i>Khóa học của tôi</RouterLink><div v-if="loading" class="app-card p-5 my-3 text-center"><span class="spinner-border text-success"></span></div><div v-else-if="error" class="alert alert-danger my-3">{{ error }} <button class="btn btn-light btn-sm ms-2" @click="loadCourse">Thử lại</button></div><template v-else><div class="hero app-card my-3"><div class="hero-art"><i class="bi bi-code-slash"></i><span>{{ course.code }}</span></div><div class="p-4"><span class="badge badge-soft-success">{{ course.category }}</span><h1>{{ course.title }}</h1><p>{{ course.description }}</p><div class="d-flex flex-wrap gap-4 small"><span><i class="bi bi-person me-1"></i>{{ course.teacher }}</span><span><i class="bi bi-journal me-1"></i>{{ lessonCount }} bài học</span><span><i class="bi bi-clock me-1"></i>{{ formatDuration(totalDuration) }}</span></div></div></div><div class="row g-4"><div class="col-lg-8"><div class="app-card p-3 p-md-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4 fw-bold mb-0">Nội dung khóa học</h2><small class="text-secondary">{{ chapters.length }} chương • {{ lessonCount }} bài</small></div><div v-if="chapters.length" class="accordion accordion-flush" id="courseContent"><div v-for="(chapter,index) in chapters" :key="chapter.id" class="accordion-item"><h3 class="accordion-header"><button class="accordion-button" :class="{collapsed:index!==0}" data-bs-toggle="collapse" :data-bs-target="`#chapter${chapter.id}`"><span class="chapter-number">{{ index+1 }}</span><span><strong>{{ chapter.title }}</strong><small>{{ chapter.lessons.length }} bài học</small></span></button></h3><div :id="`chapter${chapter.id}`" class="accordion-collapse collapse" :class="{show:index===0}" data-bs-parent="#courseContent"><div class="accordion-body p-0"><RouterLink v-for="lesson in chapter.lessons" :key="lesson.id" :to="`/lms/courses/${course.id}/lessons/${lesson.id}`" class="lesson-row" :class="{current:lesson.id===continueLessonId}"><i :class="['bi',lesson.completed?'bi-check-circle-fill':lesson.id===continueLessonId?'bi-play-circle-fill':'bi-circle']"></i><span>{{ lesson.title }}</span><small>{{ formatDuration(lesson.duration) }}</small></RouterLink></div></div></div></div><p v-else class="text-secondary">Khóa học chưa có nội dung.</p></div></div><aside class="col-lg-4"><div class="app-card p-4 sticky-lg-top" style="top:100px"><div class="d-flex justify-content-between mb-2"><strong>Tiến độ của bạn</strong><b class="text-brand">{{ course.progress }}%</b></div><div class="progress mb-3" style="height:9px"><div class="progress-bar" :style="{width:course.progress+'%'}"></div></div><div class="row text-center mb-3"><div class="col"><strong>{{ completedCount }}/{{ lessonCount }}</strong><small>Bài học</small></div><div class="col"><strong>{{ course.finalScore ?? '—' }}</strong><small>Điểm</small></div></div><RouterLink v-if="continueLessonId" :to="`/lms/courses/${course.id}/lessons/${continueLessonId}`" class="btn btn-brand w-100">{{ completedCount?'Tiếp tục học':'Bắt đầu học' }}</RouterLink></div></aside></div></template></section>
</template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute } from 'vue-router';import axiosClient from '../../api/axiosClient';const route=useRoute(),loading=ref(true),error=ref(''),chapters=ref([]),course=reactive({id:0,code:'',title:'',description:'',teacher:'',category:'Khóa học',progress:0,finalScore:null}),pick=(s,...n)=>n.map(x=>s?.[x]).find(v=>v!==undefined&&v!==null);const lessonCount=computed(()=>chapters.value.reduce((n,c)=>n+c.lessons.length,0)),completedCount=computed(()=>chapters.value.reduce((n,c)=>n+c.lessons.filter(x=>x.completed).length,0)),totalDuration=computed(()=>chapters.value.reduce((n,c)=>n+c.lessons.reduce((sum,l)=>sum+l.duration,0),0)),allLessons=computed(()=>chapters.value.flatMap(c=>c.lessons)),continueLessonId=computed(()=>allLessons.value.find(x=>!x.completed)?.id||allLessons.value[0]?.id||0);onMounted(loadCourse);async function loadCourse(){loading.value=true;error.value='';try{const data=await axiosClient.get(`/lms/courses/${Number(route.params.courseId)}`,{params:{_fresh:Date.now()}}),c=pick(data,'course','Course')||{},rows=pick(data,'lessons','Lessons')||[];Object.assign(course,{id:Number(pick(c,'Id','id')),code:pick(c,'Code','code')||'',title:pick(c,'Title','title')||'',description:pick(c,'Description','description')||pick(c,'ShortDescription','shortDescription')||'',teacher:pick(c,'TeacherName','teacherName')||'',category:pick(c,'CategoryName','categoryName')||'Khóa học',progress:Number(pick(c,'ProgressPercent','progressPercent')||0),finalScore:pick(c,'FinalScore','finalScore')});chapters.value=(pick(data,'chapters','Chapters')||[]).map(ch=>{const id=Number(pick(ch,'Id','id'));return{id,title:pick(ch,'Title','title')||'',lessons:rows.filter(l=>Number(pick(l,'ChapterId','chapterId'))===id).map(l=>({id:Number(pick(l,'Id','id')),title:pick(l,'Title','title')||'',duration:Number(pick(l,'DurationSeconds','durationSeconds')||0),completed:Boolean(pick(l,'Completed','completed'))}))}})}catch(e){error.value=e.message}finally{loading.value=false}}function formatDuration(seconds){const minutes=Math.round(Number(seconds||0)/60);return minutes>=60?`${Math.floor(minutes/60)} giờ ${minutes%60} phút`:`${minutes} phút`}
</script>
<style scoped>.hero{display:grid;grid-template-columns:260px 1fr;overflow:hidden}.hero-art{background:#07875a;color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:850}.hero-art i{font-size:4rem}.hero h1{font-size:clamp(1.7rem,3vw,2.5rem);font-weight:850;letter-spacing:-.04em;margin:.6rem 0}.hero p{color:#667870;max-width:750px}.accordion-item{border-color:#e6ece9}.accordion-button{box-shadow:none!important;background:#fff!important;color:#18332b;padding:1rem 0}.accordion-button>span:last-child{display:grid}.accordion-button small{font-size:.75rem;color:#7b8a85;font-weight:400}.chapter-number{width:34px;height:34px;border-radius:9px;background:#e9f6f1;color:#07875a;display:grid;place-items:center;margin-right:.8rem;font-weight:800}.lesson-row{display:grid;grid-template-columns:24px 1fr auto;align-items:center;gap:.55rem;padding:.78rem 1rem;border-radius:8px;color:#53655f}.lesson-row:hover,.lesson-row.current{background:#f0f7f4;color:#07875a}.lesson-row .bi-check-circle-fill{color:#07875a}.lesson-row small{color:#8a9893}.row.text-center strong,.row.text-center small{display:block}.row.text-center small{color:#80908a;font-size:.72rem}@media(max-width:767px){.hero{grid-template-columns:1fr}.hero-art{min-height:130px}}</style>
